namespace App\Http\Controllers;

use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Http;

class MailerLiteController extends Controller
{
    public function index()
    {
        return view('api-key-form');
    }

    public function validateApiKey(Request $request)
    {
        $apiKey = $request->input('api_key');

        // Check if the key already exists in the database
        $existingKey = DB::table('mailerlite_keys')->where('api_key', $apiKey)->first();

        if ($existingKey) {
            return redirect()->route('home')->with('error', 'API key already exists.');
        }

        // Validate the key against MailerLite API
        $response = Http::withHeaders([
            'X-MailerLite-ApiKey' => $apiKey,
        ])->get('https://api.mailerlite.com/api/v2/me');

        if ($response->successful()) {
            // Save the key to the database
            DB::table('mailerlite_keys')->insert([
                'api_key' => $apiKey,
            ]);

            return redirect()->route('home')->with('success', 'API key validated and saved.');
        } else {
            return redirect()->route('home')->with('error', 'Invalid API key.');
        }
    }

    public function subscribers()
    {
